// Config — replace with your values
const SUPABASE_URL = 'https://ainspdnploxzrujbgcqo.supabase.co';
const SUPABASE_KEY = 'PEGA_TU_SUPABASE_SERVICE_KEY_AQUI';
const APIFY_TOKEN = 'PEGA_TU_APIFY_TOKEN_AQUI';

const competitors = await this.helpers.httpRequest({
  method: 'GET',
  url: `${SUPABASE_URL}/rest/v1/competitor_profiles?or=(ig_status.eq.pending,tiktok_status.eq.pending)&order=created_at.asc&limit=20`,
  headers: {
    'Authorization': `Bearer ${SUPABASE_KEY}`,
    'apikey': SUPABASE_KEY
  },
  json: true
});

console.log(`Found ${competitors.length} pending competitors`);
if (competitors.length === 0) return [];

return competitors.map(c => ({
  json: {
    ...c,
    _supabase_url: SUPABASE_URL,
    _supabase_key: SUPABASE_KEY,
    _apify_token: APIFY_TOKEN
  }
}));

const comp = $input.first().json;

let runId = null;
try {
  const runs = await this.helpers.httpRequest({
    method: 'POST',
    url: `${comp._supabase_url}/rest/v1/scrape_runs`,
    headers: {
      'Authorization': `Bearer ${comp._supabase_key}`,
      'apikey': comp._supabase_key,
      'Content-Type': 'application/json',
      'Prefer': 'return=representation'
    },
    body: {
      source: 'instagram',
      keyword: comp.fb_page_name,
      competitor_id: comp.id,
      status: 'running',
      max_results: 1
    },
    json: true
  });
  runId = runs[0]?.id || null;
} catch(e) {
  console.log('Create run error:', e.message);
}

return [{ json: { ...comp, _run_id: runId } }];

const comp = $input.first().json;

if (comp.ig_status !== 'pending') {
  console.log(`Skipping IG for ${comp.fb_page_name} — status: ${comp.ig_status}`);
  return [{ json: { ...comp, _ig_result: 'skipped' } }];
}

const fbUrl = comp.fb_page_url || `https://www.facebook.com/${comp.fb_page_id}`;
console.log(`Looking for IG handle of ${comp.fb_page_name} via ${fbUrl}`);

try {
  const pages = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/apify~facebook-pages-scraper/run-sync-get-dataset-items?token=${comp._apify_token}&timeout=120`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      startUrls: [{ url: fbUrl }],
      maxPages: 1
    },
    json: true,
    timeout: 150000
  });

  const page = pages[0];
  if (!page) {
    console.log('No page data returned');
    return [{ json: { ...comp, _ig_result: 'not_found' } }];
  }

  let igHandle = null;
  let igUrl = null;
  const igPatterns = [
    /instagram\.com\/([a-zA-Z0-9_.]+)/,
    /ig:\s*@?([a-zA-Z0-9_.]+)/i,
    /instagram:\s*@?([a-zA-Z0-9_.]+)/i
  ];

  const pageStr = JSON.stringify(page);
  for (const pattern of igPatterns) {
    const match = pageStr.match(pattern);
    if (match && match[1] && !['p', 'reel', 'stories', 'explore'].includes(match[1])) {
      igHandle = match[1];
      igUrl = `https://instagram.com/${igHandle}`;
      break;
    }
  }

  if (igHandle) {
    console.log(`Found IG: @${igHandle}`);
    return [{ json: { ...comp, _ig_result: 'found', _ig_handle: igHandle, _ig_url: igUrl } }];
  } else {
    console.log('No IG handle found in page data');
    return [{ json: { ...comp, _ig_result: 'not_found' } }];
  }

} catch(e) {
  console.log('IG enrichment error:', e.message);
  return [{ json: { ...comp, _ig_result: 'error', _ig_error: e.message } }];
}

const comp = $input.first().json;

if (comp.tiktok_status !== 'pending') {
  console.log(`Skipping TikTok for ${comp.fb_page_name} — status: ${comp.tiktok_status}`);
  return [{ json: { ...comp, _tiktok_result: 'skipped' } }];
}

console.log(`Searching TikTok for ${comp.fb_page_name}`);

try {
  const results = await this.helpers.httpRequest({
    method: 'POST',
    url: `https://api.apify.com/v2/acts/clockworks~tiktok-scraper/run-sync-get-dataset-items?token=${comp._apify_token}&timeout=120`,
    headers: { 'Content-Type': 'application/json' },
    body: {
      searchQueries: [comp.fb_page_name],
      resultsPerPage: 5,
      searchSection: 'users',
      shouldDownloadVideos: false
    },
    json: true,
    timeout: 150000
  });

  if (!results || results.length === 0) {
    console.log('No TikTok results');
    return [{ json: { ...comp, _tiktok_result: 'not_found' } }];
  }

  const searchName = comp.fb_page_name.toLowerCase().replace(/[^a-z0-9]/g, '');
  let bestMatch = null;
  let bestScore = 0;

  for (const user of results) {
    const userName = (user.uniqueId || user.nickname || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    const nickName = (user.nickname || '').toLowerCase().replace(/[^a-z0-9]/g, '');
    let score = 0;
    if (userName === searchName || nickName === searchName) score = 100;
    else if (userName.includes(searchName) || searchName.includes(userName)) score = 80;
    else if (nickName.includes(searchName) || searchName.includes(nickName)) score = 70;
    if (score > bestScore) { bestScore = score; bestMatch = user; }
  }

  if (bestMatch && bestScore >= 70) {
    const handle = bestMatch.uniqueId || bestMatch.id;
    console.log(`Found TikTok: @${handle} (score: ${bestScore})`);
    return [{ json: { ...comp, _tiktok_result: 'found', _tiktok_handle: handle, _tiktok_url: `https://tiktok.com/@${handle}` } }];
  } else {
    console.log('No matching TikTok profile found');
    return [{ json: { ...comp, _tiktok_result: 'not_found' } }];
  }

} catch(e) {
  console.log('TikTok enrichment error:', e.message);
  return [{ json: { ...comp, _tiktok_result: 'not_found' } }];
}

const comp = $input.first().json;
const now = new Date().toISOString();

const updateBody = { updated_at: now };

if (comp._ig_result === 'found') {
  updateBody.ig_handle = comp._ig_handle;
  updateBody.ig_profile_url = comp._ig_url;
  updateBody.ig_status = 'found';
  updateBody.ig_enriched_at = now;
} else if (comp._ig_result === 'not_found' || comp._ig_result === 'error') {
  updateBody.ig_status = 'not_found';
  updateBody.ig_enriched_at = now;
}

if (comp._tiktok_result === 'found') {
  updateBody.tiktok_handle = comp._tiktok_handle;
  updateBody.tiktok_profile_url = comp._tiktok_url;
  updateBody.tiktok_status = 'found';
  updateBody.tiktok_enriched_at = now;
} else if (comp._tiktok_result === 'not_found' || comp._tiktok_result === 'error') {
  updateBody.tiktok_status = 'not_found';
  updateBody.tiktok_enriched_at = now;
}

console.log(`Updating ${comp.fb_page_name}: IG=${comp._ig_result}, TikTok=${comp._tiktok_result}`);

try {
  await this.helpers.httpRequest({
    method: 'PATCH',
    url: `${comp._supabase_url}/rest/v1/competitor_profiles?id=eq.${comp.id}`,
    headers: {
      'Authorization': `Bearer ${comp._supabase_key}`,
      'apikey': comp._supabase_key,
      'Content-Type': 'application/json',
      'Prefer': 'return=minimal'
    },
    body: updateBody,
    json: true
  });
} catch(e) {
  console.log('Update failed:', e.message);
}

if (comp._run_id) {
  const totalAnalyzed = (comp._ig_result === 'found' ? 1 : 0) + (comp._tiktok_result === 'found' ? 1 : 0);
  const totalErrors = (comp._ig_result === 'error' ? 1 : 0) + (comp._tiktok_result === 'error' ? 1 : 0);
  try {
    await this.helpers.httpRequest({
      method: 'PATCH',
      url: `${comp._supabase_url}/rest/v1/scrape_runs?id=eq.${comp._run_id}`,
      headers: {
        'Authorization': `Bearer ${comp._supabase_key}`,
        'apikey': comp._supabase_key,
        'Content-Type': 'application/json',
        'Prefer': 'return=minimal'
      },
      body: {
        status: totalErrors > 0 ? 'partial' : 'completed',
        completed_at: now,
        total_scraped: 1,
        total_analyzed: totalAnalyzed,
        total_errors: totalErrors
      },
      json: true
    });
  } catch(e) {
    console.log('Run update failed:', e.message);
  }
}

return [{ json: { id: comp.id, fb_page_name: comp.fb_page_name, ig: comp._ig_result, tiktok: comp._tiktok_result } }];
